const dockerComposeTemplate = `version: '3.8'

# Hyperion Local Development Stack
# Auto-generated by 'hyper init'
#
# Services:
#   - MongoDB: Primary database (port 27017)
#   - Qdrant: Vector database (ports 7333-7334)
#   - Ollama: GPU-accelerated embeddings (port 7335)
#
# Usage:
#   docker compose up -d              # Start all services
#   docker compose logs -f ollama     # Watch Ollama model download
#   docker compose down               # Stop all services
#   docker compose down -v            # Stop and remove data

services:
  # ==========================================
  # MongoDB - Primary Database
  # ==========================================
  mongodb:
    image: mongo:7.0
    container_name: hyper-mongodb
    ports:
      - "27017:27017"
    environment:
      MONGO_INITDB_ROOT_USERNAME: admin
      MONGO_INITDB_ROOT_PASSWORD: admin123
      MONGO_INITDB_DATABASE: hyper_db
    volumes:
      - hyper_mongodb_data:/data/db
      - hyper_mongodb_config:/data/configdb
    networks:
      - hyper-network
    healthcheck:
      test: ["CMD", "mongosh", "--eval", "db.adminCommand('ping')"]
      interval: 10s
      timeout: 5s
      retries: 5
      start_period: 10s
    restart: unless-stopped

  # ==========================================
  # Qdrant - Vector Database
  # ==========================================
  qdrant:
    image: qdrant/qdrant:latest
    container_name: hyper-qdrant
    ports:
      - "7333:6333"  # HTTP API (custom port to avoid collisions)
      - "7334:6334"  # gRPC API (custom port to avoid collisions)
    volumes:
      - hyper_qdrant_data:/qdrant/storage
    networks:
      - hyper-network
    healthcheck:
      test: ["CMD", "wget", "--no-verbose", "--tries=1", "-O", "/dev/null", "http://localhost:6333/health"]
      interval: 10s
      timeout: 5s
      retries: 5
      start_period: 10s
    restart: unless-stopped

  # ==========================================
  # Ollama - GPU-Accelerated Embeddings
  # ==========================================
  ollama:
    image: ollama/ollama:latest
    container_name: hyper-ollama
    ports:
      - "7335:11434"  # API (custom port to avoid collisions)
    environment:
      OLLAMA_HOST: 0.0.0.0:11434
      OLLAMA_NUM_PARALLEL: 4
    volumes:
      - hyper_ollama_data:/root/.ollama
    networks:
      - hyper-network
    # Uncomment for NVIDIA GPU support
    # deploy:
    #   resources:
    #     reservations:
    #       devices:
    #         - driver: nvidia
    #           count: 1
    #           capabilities: [gpu]
    healthcheck:
      test: ["CMD", "curl", "-f", "http://localhost:11434/api/tags"]
      interval: 10s
      timeout: 5s
      retries: 5
      start_period: 10s
    restart: unless-stopped

  # ==========================================
  # Ollama Model Puller
  # Downloads nomic-embed-text model on first run
  # ==========================================
  ollama-pull:
    image: ollama/ollama:latest
    container_name: hyper-ollama-pull
    depends_on:
      ollama:
        condition: service_healthy
    entrypoint: /bin/sh
    command: >
      -c "
      echo '========================================';
      echo 'Downloading nomic-embed-text model...';
      echo 'This may take 2-5 minutes on first run';
      echo '========================================';
      ollama pull nomic-embed-text;
      echo '';
      echo '========================================';
      echo '✅ Model downloaded successfully!';
      echo 'Model: nomic-embed-text (768 dimensions)';
      echo 'Ollama URL: http://localhost:7335';
      echo '========================================';
      "
    environment:
      OLLAMA_HOST: ollama:11434
    networks:
      - hyper-network

# ==========================================
# Networks
# ==========================================
networks:
  hyper-network:
    driver: bridge
    name: hyper-network

# ==========================================
# Volumes (Persistent Storage)
# ==========================================
volumes:
  hyper_mongodb_data:
    driver: local
  hyper_mongodb_config:
    driver: local
  hyper_qdrant_data:
    driver: local
  hyper_ollama_data:
    driver: local
`

