// ProviderConfig holds AI provider configuration
type ProviderConfig struct {
	Provider string
	Model    string
	Token    string
	APIURL   string
}

// validateOpenAI validates OpenAI API key
func validateOpenAI(apiKey string, model string, apiURL string) error {
	if apiURL == "" {
		apiURL = "https://api.openai.com/v1"
	}

	// Test with models endpoint (simple and fast)
	url := apiURL + "/models"
	req, err := http.NewRequest("GET", url, nil)
	if err != nil {
		return fmt.Errorf("failed to create request: %w", err)
	}

	req.Header.Set("Authorization", "Bearer "+apiKey)

	client := &http.Client{Timeout: 10 * time.Second}
	resp, err := client.Do(req)
	if err != nil {
		return fmt.Errorf("failed to connect to OpenAI API: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode == 401 {
		return fmt.Errorf("invalid API key (HTTP 401)")
	}
	if resp.StatusCode != 200 {
		body, _ := io.ReadAll(resp.Body)
		return fmt.Errorf("API returned error (HTTP %d): %s", resp.StatusCode, string(body))
	}

	fmt.Println("✅ OpenAI API key validated successfully")
	return nil
}

// validateAnthropic validates Anthropic API key
func validateAnthropic(apiKey string, model string, apiURL string) error {
	if apiURL == "" {
		apiURL = "https://api.anthropic.com/v1"
	}

	// Test with messages endpoint (minimal request)
	url := apiURL + "/messages"
	payload := map[string]interface{}{
		"model":      model,
		"max_tokens": 1,
		"messages": []map[string]string{
			{"role": "user", "content": "test"},
		},
	}

	jsonData, err := json.Marshal(payload)
	if err != nil {
		return fmt.Errorf("failed to create request: %w", err)
	}

	req, err := http.NewRequest("POST", url, bytes.NewBuffer(jsonData))
	if err != nil {
		return fmt.Errorf("failed to create request: %w", err)
	}

	req.Header.Set("x-api-key", apiKey)
	req.Header.Set("anthropic-version", "2023-06-01")
	req.Header.Set("Content-Type", "application/json")

	client := &http.Client{Timeout: 15 * time.Second}
	resp, err := client.Do(req)
	if err != nil {
		return fmt.Errorf("failed to connect to Anthropic API: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode == 401 {
		return fmt.Errorf("invalid API key (HTTP 401)")
	}
	// 400 is ok - means API key works but request was invalid (expected for minimal test)
	if resp.StatusCode != 200 && resp.StatusCode != 400 {
		body, _ := io.ReadAll(resp.Body)
		return fmt.Errorf("API returned error (HTTP %d): %s", resp.StatusCode, string(body))
	}

	fmt.Println("✅ Anthropic API key validated successfully")
	return nil
}

// validateVoyageAI validates Voyage AI API key
func validateVoyageAI(apiKey string, model string, apiURL string) error {
	if apiURL == "" {
		apiURL = "https://api.voyageai.com/v1"
	}

	// Test with embeddings endpoint
	url := apiURL + "/embeddings"
	payload := map[string]interface{}{
		"input": []string{"test"},
		"model": model,
	}

	jsonData, err := json.Marshal(payload)
	if err != nil {
		return fmt.Errorf("failed to create request: %w", err)
	}

	req, err := http.NewRequest("POST", url, bytes.NewBuffer(jsonData))
	if err != nil {
		return fmt.Errorf("failed to create request: %w", err)
	}

	req.Header.Set("Authorization", "Bearer "+apiKey)
	req.Header.Set("Content-Type", "application/json")

	client := &http.Client{Timeout: 15 * time.Second}
	resp, err := client.Do(req)
	if err != nil {
		return fmt.Errorf("failed to connect to Voyage AI API: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode == 401 {
		return fmt.Errorf("invalid API key (HTTP 401)")
	}
	if resp.StatusCode != 200 {
		body, _ := io.ReadAll(resp.Body)
		return fmt.Errorf("API returned error (HTTP %d): %s", resp.StatusCode, string(body))
	}

	fmt.Println("✅ Voyage AI API key validated successfully")
	return nil
}

// validateProvider validates the provider configuration
func validateProvider(config *ProviderConfig) error {
	if config == nil || config.Provider == "" {
		// No provider specified, skip validation (will use Ollama default)
		return nil
	}

	fmt.Printf("\n🔐 Validating %s API credentials...\n", config.Provider)

	switch strings.ToLower(config.Provider) {
	case "openai":
		if config.Token == "" {
			return fmt.Errorf("OpenAI API token is required (use -token flag)")
		}
		if config.Model == "" {
			config.Model = "gpt-4" // Default model
		}
		return validateOpenAI(config.Token, config.Model, config.APIURL)

	case "anthropic", "claude":
		if config.Token == "" {
			return fmt.Errorf("Anthropic API token is required (use -token flag)")
		}
		if config.Model == "" {
			config.Model = "claude-sonnet-4-20250514" // Default model
		}
		return validateAnthropic(config.Token, config.Model, config.APIURL)

	case "voyage", "voyageai":
		if config.Token == "" {
			return fmt.Errorf("Voyage AI API token is required (use -token flag)")
		}
		if config.Model == "" {
			config.Model = "voyage-3" // Default model
		}
		return validateVoyageAI(config.Token, config.Model, config.APIURL)

	case "ollama":
		// Ollama doesn't require API key validation
		fmt.Println("ℹ️  Ollama selected - no API key validation needed")
		return nil

	default:
		return fmt.Errorf("unsupported provider: %s (supported: openai, anthropic, voyage, ollama)", config.Provider)
	}
}

// generateEnvWithProvider creates .env.hyper with provider configuration
func generateEnvWithProvider(config *ProviderConfig) string {
	env := envTemplate

	if config != nil && config.Provider != "" {
		provider := strings.ToLower(config.Provider)

		// Add AI provider configuration at the end
		aiConfig := "\n\n# ==========================================\n"
		aiConfig += "# AI PROVIDER CONFIGURATION\n"
		aiConfig += "# ==========================================\n"

		switch provider {
		case "openai":
			aiConfig += fmt.Sprintf("AI_PROVIDER=openai\n")
			aiConfig += fmt.Sprintf("OPENAI_API_KEY=%s\n", config.Token)
			aiConfig += fmt.Sprintf("AI_MODEL=%s\n", config.Model)
			if config.APIURL != "" {
				aiConfig += fmt.Sprintf("OPENAI_BASE_URL=%s\n", config.APIURL)
			}

			// Update embedding section
			env = strings.Replace(env, "EMBEDDING=ollama", "# EMBEDDING=ollama  # Using OpenAI for AI", 1)
			env = strings.Replace(env, "OLLAMA_URL=http://localhost:7335", "# OLLAMA_URL=http://localhost:7335", 1)
			env = strings.Replace(env, "OLLAMA_MODEL=nomic-embed-text", "# OLLAMA_MODEL=nomic-embed-text", 1)

		case "anthropic", "claude":
			aiConfig += fmt.Sprintf("AI_PROVIDER=anthropic\n")
			aiConfig += fmt.Sprintf("ANTHROPIC_API_KEY=%s\n", config.Token)
			aiConfig += fmt.Sprintf("AI_MODEL=%s\n", config.Model)
			if config.APIURL != "" {
				aiConfig += fmt.Sprintf("ANTHROPIC_BASE_URL=%s\n", config.APIURL)
			}

			// Keep Ollama for embeddings (Anthropic doesn't provide embeddings)
			aiConfig += "\n# Note: Still using Ollama for embeddings (Anthropic doesn't provide embeddings)\n"

		case "voyage", "voyageai":
			aiConfig += fmt.Sprintf("AI_PROVIDER=voyage\n")
			aiConfig += fmt.Sprintf("VOYAGE_API_KEY=%s\n", config.Token)

			// Update embedding section to use Voyage
			env = strings.Replace(env, "EMBEDDING=ollama", "EMBEDDING=voyage", 1)
			env = strings.Replace(env, "OLLAMA_URL=http://localhost:7335", "# OLLAMA_URL=http://localhost:7335", 1)
			env = strings.Replace(env, "OLLAMA_MODEL=nomic-embed-text", "# OLLAMA_MODEL=nomic-embed-text", 1)
			env = strings.Replace(env, "# EMBEDDING=voyage\n# VOYAGE_API_KEY=pa-your-key-here\n# VOYAGE_MODEL=voyage-3",
				fmt.Sprintf("# Voyage AI configured above\nVOYAGE_MODEL=%s", config.Model), 1)

			if config.APIURL != "" {
				aiConfig += fmt.Sprintf("VOYAGE_BASE_URL=%s\n", config.APIURL)
			}
		}

		env += aiConfig
	}

	return env
}

// Init creates a new Hyperion setup in the current directory
func Init(config *ProviderConfig) error {
	// Validate provider configuration if provided
	if err := validateProvider(config); err != nil {
		return fmt.Errorf("provider validation failed: %w", err)
	}
	// Check if files already exist
	files := []string{"docker-compose.yml", ".env.hyper"}
	var existingFiles []string

	for _, file := range files {
		if _, err := os.Stat(file); err == nil {
			existingFiles = append(existingFiles, file)
		}
	}

	if len(existingFiles) > 0 {
		fmt.Println("⚠️  The following files already exist:")
		for _, file := range existingFiles {
			fmt.Printf("   - %s\n", file)
		}
		fmt.Println()
		fmt.Print("Do you want to overwrite them? (yes/no): ")

		var response string
		fmt.Scanln(&response)

		if response != "yes" && response != "y" {
			return fmt.Errorf("initialization cancelled - files already exist")
		}
		fmt.Println()
	}

	// Create docker-compose.yml
	fmt.Println("📝 Creating docker-compose.yml...")
	if err := os.WriteFile("docker-compose.yml", []byte(dockerComposeTemplate), 0644); err != nil {
		return fmt.Errorf("failed to create docker-compose.yml: %w", err)
	}
	fmt.Println("✅ docker-compose.yml created")

	// Create .env.hyper with provider configuration
	fmt.Println("📝 Creating .env.hyper...")
	envContent := generateEnvWithProvider(config)
	if err := os.WriteFile(".env.hyper", []byte(envContent), 0644); err != nil {
		return fmt.Errorf("failed to create .env.hyper: %w", err)
	}
	fmt.Println("✅ .env.hyper created")

	// Create README.md
	fmt.Println("📝 Creating HYPER_README.md...")
	if err := os.WriteFile("HYPER_README.md", []byte(readmeTemplate), 0644); err != nil {
		return fmt.Errorf("failed to create HYPER_README.md: %w", err)
	}
	fmt.Println("✅ HYPER_README.md created")

	// Get current directory
	cwd, err := os.Getwd()
	if err != nil {
		cwd = "current directory"
	} else {
		cwd = filepath.Base(cwd)
	}

	// Print success message
	fmt.Println()
	fmt.Println("🎉 Hyperion initialized successfully!")
	fmt.Println("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
	fmt.Println()
	fmt.Println("📁 Location:", cwd)
	fmt.Println()
	fmt.Println("📝 Files created:")
	fmt.Println("   ✓ docker-compose.yml  - MongoDB + Qdrant + Ollama")
	fmt.Println("   ✓ .env.hyper          - Configuration file")
	fmt.Println("   ✓ HYPER_README.md     - Setup instructions")
	fmt.Println()
	fmt.Println("🚀 Next steps:")
	fmt.Println()
	fmt.Println("   1. Start services:")
	fmt.Println("      docker compose up -d")
	fmt.Println()
	fmt.Println("   2. Watch Ollama model download (first time, 2-5 min):")
	fmt.Println("      docker compose logs -f ollama-pull")
	fmt.Println()
	fmt.Println("   3. Run Hyper:")
	fmt.Println("      hyper --mode=http")
	fmt.Println()
	fmt.Println("   4. Open browser:")
	fmt.Println("      http://localhost:7095")
	fmt.Println()
	fmt.Println("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
	fmt.Println()

	// Provider-specific tips
	if config != nil && config.Provider != "" {
		provider := strings.ToLower(config.Provider)
		fmt.Println("🔧 Provider Configuration:")
		fmt.Printf("   Provider: %s\n", provider)
		fmt.Printf("   Model: %s\n", config.Model)
		fmt.Printf("   Token: %s...%s\n", config.Token[:8], config.Token[len(config.Token)-4:])
		if config.APIURL != "" {
			fmt.Printf("   API URL: %s\n", config.APIURL)
		}
		fmt.Println()
	}

	fmt.Println("💡 Tip: Edit .env.hyper to customize your setup")
	fmt.Println("📖 See HYPER_README.md for detailed instructions")
	fmt.Println()

	return nil
}
